def greatest_rows(readings):
    best = None
    winners = []
    for i in range(len(readings)):
        total = 0
        for value in readings[i]:
            total += value
        if best is None or total > best:
            best = total
            winners = [i]
        elif total == best:
            winners.append(i)
    return best, winners

